            try{int n=BackendChecks(Path.Combine(qa.output,"cases"),args.Contains("--round-trip-restart"));File.WriteAllText(Path.Combine(qa.output,"backend-result.txt"),"PASS: "+n);qa.StartCoroutine(qa.Guard());}catch(Exception e){qa.Fail(e);}
        }
        void Fail(Exception e){File.WriteAllText(Path.Combine(output,"failure.txt"),e.ToString());Debug.LogException(e);Application.Quit(1);}
        IEnumerator Guard(){var run=Run();while(true){bool more;try{more=run.MoveNext();}catch(Exception e){Fail(e);yield break;}if(!more)yield break;yield return run.Current;}}
